static int inside(int px,int py,int x,int y,int w,int h){return px>=x&&py>=y&&px<x+w&&py<y+h;}
static void u32s(uint32_t v,char*out){char t[16];int n=0;if(!v){out[0]='0';out[1]=0;return;}while(v&&n<15){t[n++]=(char)('0'+v%10);v/=10;}for(int i=0;i<n;i++)out[i]=t[n-1-i];out[n]=0;}
static void append_text(const char*s){if(!s)return;int n=(int)strlen(s);if(n<=0)return;if(n>=MAX_TERMINAL){s+=n-(MAX_TERMINAL-1);n=MAX_TERMINAL-1;}if(terminal_output_len+n>=MAX_TERMINAL){int d=terminal_output_len+n-MAX_TERMINAL+1;memmove(terminal_output,terminal_output+d,terminal_output_len-d);terminal_output_len-=d;}memcpy(terminal_output+terminal_output_len,s,n);terminal_output_len+=n;terminal_output[terminal_output_len]=0;}
void terminal_route_output(int pid,const char*s){if(pid==terminal_pid)append_text(s);}
void gui_blit_fullscreen(const uint32_t*pixels,int owner_pid){if(!pixels)return;memcpy(fullscreen_buffer,pixels,sizeof(fullscreen_buffer));fullscreen_active=1;fullscreen_owner=owner_pid;}

static uint32_t accent(void){struct nova_settings s;nova_settings_get(&s);return s.accent==1?PURPLE:s.accent==2?GREEN:s.accent==3?AMBER:CYAN;}
static uint32_t sev(uint8_t s){return s==NOVA_SUCCESS?GREEN:s==NOVA_WARNING?AMBER:s==NOVA_ERROR?RED:BLUE;}
static void panel(int x,int y,int w,int h,int r,uint32_t c){fb_fill_rounded_rect(x+5,y+7,w,h,r,0x02030A);fb_fill_rounded_rect(x,y,w,h,r,c);fb_draw_rect(x,y,w,h,BORDER);}
static void glow_line(int x,int y,int w,uint32_t c){fb_fill_rect(x,y,w,1,c);fb_fill_rect(x,y+1,w,1,c);}
static void orb(int cx,int cy,int r,uint32_t c,int a){for(int y=-r;y<=r;y+=3)for(int x=-r;x<=r;x+=3){int d=x*x+y*y;if(d<=r*r)fb_blend_pixel(cx+x,cy+y,c,(uint8_t)(5+((r*r-d)*a)/(r*r)));}}

static void wallpaper(void){int w=(int)fb_width(),h=(int)fb_height();fb_fill_gradient_v(0,0,w,h,BG1,BG0);uint32_t t=pit_ticks();orb(w-130+(int)((t/8)%80),110,210,PURPLE,80);orb(w/2,h-90,250,BLUE,65);orb(80,180,170,PINK,55);for(int y=0;y<h;y+=28)fb_draw_line(0,y,w,y,0x0B1120);for(int x=0;x<w;x+=28)fb_draw_line(x,0,x,h,0x09101C);for(int i=0;i<24;i++){int x=(i*97+(int)t/3)%w;int y=(i*53+(int)t/5)%h;fb_fill_rect(x,y,2,2,i%3?CYAN:PINK);}}

