static void dock(void){int w=(int)fb_width(),h=(int)fb_height();int dw=704,x=(w-dw)/2,y=h-DOCK_H+8;panel(x,y,dw,50,16,0x121A2D);for(int i=0;i<nova_app_count();i++){const struct nova_app_descriptor*a=nova_app_at(i);int bx=x+12+i*74;fb_fill_rounded_rect(bx,y+8,56,34,11,a->id==active_app?PANEL2:CARD);fb_fill_rounded_rect(bx+9,y+11,28,28,9,a->accent);fb_draw_string(bx+17,y+21,a->glyph,BG0,1);if(a->id==active_app)fb_fill_rounded_rect(bx+20,y+44,16,3,2,a->accent);}fb_fill_rounded_rect(x+dw-44,y+8,32,34,11,window_mode?GREEN:PINK);fb_draw_string(x+dw-35,y+20,window_mode?"W":"+",BG0,1);}

static void draw_window_frame(struct nova_window*w){if(!w||!(w->flags&NOVA_WINDOW_VISIBLE)||(w->flags&NOVA_WINDOW_MINIMIZED))return;panel(w->x,w->y,w->w,w->h,14,CARD);fb_fill_rounded_rect(w->x,w->y,w->w,32,14,PANEL2);fb_fill_rect(w->x,w->y+28,w->w,4,PANEL2);fb_fill_rounded_rect(w->x+10,w->y+10,10,10,5,w->accent);fb_draw_string(w->x+30,w->y+10,w->title,TEXT,1);fb_fill_rounded_rect(w->x+w->w-54,w->y+8,14,14,5,AMBER);fb_fill_rounded_rect(w->x+w->w-32,w->y+8,14,14,5,RED);fb_fill_rounded_rect(w->x+w->w-14,w->y+w->h-14,10,10,3,w->accent);if(w->app_id==NOVA_APP_TERMINAL)draw_terminal_text(w->x+12,w->y+42,w->w-24,w->h-54);else if(w->app_id==NOVA_APP_BROWSER){fb_draw_string(w->x+12,w->y+44,browser_state.title[0]?browser_state.title:"Browser ready",TEXT,1);fb_draw_string(w->x+12,w->y+64,browser_state.url[0]?browser_state.url:"Enter URL in full browser workspace",MUTED,1);}else if(w->app_id==NOVA_APP_EDITOR){fb_draw_string(w->x+12,w->y+44,editor_state.filename,TEXT,1);fb_draw_string(w->x+12,w->y+64,editor_state.dirty?"Unsaved changes":"Saved",editor_state.dirty?AMBER:GREEN,1);}}
static void windows_overlay(void){if(!window_mode)return;for(int i=0;i<nova_wm_count();i++)draw_window_frame(nova_wm_at_z(i));}

static void overlay_panels(void){int w=(int)fb_width();if(notices_open){int x=w-382,y=TOP_H+10;panel(x,y,364,388,18,PANEL);fb_draw_string(x+18,y+18,"NOTIFICATION STACK",TEXT,1);for(int i=0;i<nova_notice_count()&&i<6;i++){struct nova_notice n;if(!nova_notice_read(i,&n))continue;int ny=y+50+i*52;fb_fill_rounded_rect(x+14,ny,336,42,11,CARD);fb_fill_rounded_rect(x+26,ny+15,10,10,5,sev(n.severity));fb_draw_string(x+48,ny+9,n.title,TEXT,1);fb_draw_string(x+48,ny+25,n.text,MUTED,1);}}if(control_open){int x=w-344,y=TOP_H+10;panel(x,y,326,286,18,PANEL);fb_draw_string(x+18,y+18,"CONTROL CENTER",TEXT,1);const char*l[]={"ACCENT","MOTION","COMPACT","PERFORMANCE","SAVE","SHUTDOWN"};for(int i=0;i<6;i++){int bx=x+16+(i%2)*148,by=y+50+(i/2)*64;fb_fill_rounded_rect(bx,by,138,52,12,i==5?0x4A1730:CARD);fb_fill_rounded_rect(bx+12,by+14,18,18,7,i==5?RED:accent());fb_draw_string(bx+40,by+19,l[i],TEXT,1);}}}

static void cursor(int x,int y){fb_fill_triangle(x,y,x,y+22,x+15,y+15,TEXT);fb_draw_line(x,y,x,y+22,BG0);fb_draw_line(x,y,x+15,y+15,BG0);}
static void ensure_window(enum nova_app_id id){if(id==NOVA_APP_TERMINAL&&terminal_window<0)terminal_window=nova_wm_open(id,"Nova Terminal",240,100,620,360,PURPLE,NOVA_WINDOW_RESIZABLE|NOVA_WINDOW_CLOSABLE);else if(id==NOVA_APP_BROWSER&&browser_window<0)browser_window=nova_wm_open(id,"Nova Browser",310,130,650,390,CYAN,NOVA_WINDOW_RESIZABLE|NOVA_WINDOW_CLOSABLE);else if(id==NOVA_APP_EDITOR&&editor_window<0)editor_window=nova_wm_open(id,"Nova Editor",360,160,610,380,PINK,NOVA_WINDOW_RESIZABLE|NOVA_WINDOW_CLOSABLE);}
static void select_app(enum nova_app_id id){active_app=id;launcher_open=control_open=notices_open=0;nova_event_emit(NOVA_INFO,"desktop",nova_app_get(id)->name);if(id==NOVA_APP_FILES&&fat32_is_mounted())file_count=fat32_list_dir(fat32_root_cluster(),files,18);if(window_mode)ensure_window(id);}
static void toggle_setting(int i){struct nova_settings s;nova_settings_get(&s);if(i==0)s.accent=(s.accent+1)%4;else if(i==1)s.reduced_motion=!s.reduced_motion;else if(i==2)s.compact_mode=!s.compact_mode;else if(i==3)s.performance_mode=!s.performance_mode;else if(i==4)s.show_seconds=!s.show_seconds;nova_settings_set(&s);}
static void execute_terminal(void){append_text("\n> ");append_text(terminal_input);append_text("\n");terminal_pid=shell_execute(terminal_input,&terminal_cwd,append_text);terminal_input_len=0;terminal_input[0]=0;}
static void browser_go(void){if(!browser_url_len){strcpy(browser_url,"http://example.com");browser_url_len=(int)strlen(browser_url);}nova_event_emit(NOVA_INFO,"browser","Navigation started");if(nova_browser_navigate(&browser_state,browser_url,(int)fb_width()-SIDE_W-90))nova_notice_post(NOVA_SUCCESS,"Page loaded",browser_state.title);else nova_notice_post(NOVA_ERROR,"Navigation failed",browser_state.title);}
static void key(char c){if(c=='`'){window_mode=!window_mode;if(window_mode){ensure_window(NOVA_APP_TERMINAL);ensure_window(NOVA_APP_BROWSER);ensure_window(NOVA_APP_EDITOR);}return;}if(!window_mode&&active_app!=NOVA_APP_TERMINAL&&active_app!=NOVA_APP_BROWSER&&active_app!=NOVA_APP_EDITOR&&c>='1'&&c<='9'){select_app((enum nova_app_id)(c-'1'));return;}if(active_app==NOVA_APP_TERMINAL){if(c=='\n'||c=='\r')execute_terminal();else if(c=='\b'){if(terminal_input_len>0)terminal_input[--terminal_input_len]=0;}else if(c>=32&&c<127&&terminal_input_len<MAX_INPUT-1){terminal_input[terminal_input_len++]=c;terminal_input[terminal_input_len]=0;}}else if(active_app==NOVA_APP_BROWSER){if(c=='\n'||c=='\r')browser_go();else if(c=='\b'){if(browser_url_len>0)browser_url[--browser_url_len]=0;}else if(c>=32&&c<127&&browser_url_len<BROWSER_URL_CAP-1){browser_url[browser_url_len++]=c;browser_url[browser_url_len]=0;}}else if(active_app==NOVA_APP_EDITOR){if(c=='\b')nova_editor_backspace(&editor_state);else if(c=='\n'||c=='\r')nova_editor_insert(&editor_state,'\n');else if(c>=32&&c<127)nova_editor_insert(&editor_state,c);}}

static void click(int mx,int my){int w=(int)fb_width(),h=(int)fb_height();if(inside(mx,my,w-210,9,42,30)){window_mode=!window_mode;if(window_mode){ensure_window(NOVA_APP_TERMINAL);ensure_window(NOVA_APP_BROWSER);ensure_window(NOVA_APP_EDITOR);}return;}if(inside(mx,my,w-160,9,38,30)){notices_open=!notices_open;control_open=0;return;}if(inside(mx,my,w-114,9,38,30)){control_open=!control_open;notices_open=0;return;}if(inside(mx,my,w-68,9,52,30)){power_shutdown();return;}if(window_mode){int id=nova_wm_hit_test(mx,my);if(id>=0){struct nova_window*win=nova_wm_get(id);if(inside(mx,my,win->x+win->w-36,win->y+4,22,24)){nova_wm_close(id);if(id==terminal_window)terminal_window=-1;if(id==browser_window)browser_window=-1;if(id==editor_window)editor_window=-1;return;}if(inside(mx,my,win->x+win->w-58,win->y+4,22,24)){nova_wm_toggle_maximize(id);return;}active_app=(enum nova_app_id)win->app_id;nova_wm_begin_pointer(mx,my);return;}}if(control_open){int x=w-344,y=TOP_H+10;for(int i=0;i<6;i++){int bx=x+16+(i%2)*148,by=y+50+(i/2)*64;if(inside(mx,my,bx,by,138,52)){if(i<4)toggle_setting(i);else if(i==4)nova_settings_save();else power_shutdown();return;}}return;}for(int i=0;i<nova_app_count();i++){int sy=TOP_H+40+i*36;if(inside(mx,my,10,sy,SIDE_W-20,30)){select_app((enum nova_app_id)i);return;}}int dw=704,dx=(w-dw)/2,dy=h-DOCK_H+8;for(int i=0;i<nova_app_count();i++)if(inside(mx,my,dx+12+i*74,dy+8,56,34)){select_app((enum nova_app_id)i);return;}if(active_app==NOVA_APP_BROWSER){int x=SIDE_W+22,y=TOP_H+18,bw=(int)fb_width()-x-18;if(inside(mx,my,x+bw-86,y+10,66,30)){browser_go();return;}}if(active_app==NOVA_APP_EDITOR){int x=SIDE_W+22,y=TOP_H+18,ew=(int)fb_width()-x-18;if(inside(mx,my,x+ew-176,y+10,70,30)){nova_editor_new(&editor_state,"UNTITLED.TXT");return;}if(inside(mx,my,x+ew-96,y+10,76,30)){int ok=nova_editor_save(&editor_state);nova_notice_post(ok?NOVA_SUCCESS:NOVA_ERROR,ok?"File saved":"Save failed",editor_state.filename);return;}}if(active_app==NOVA_APP_SETTINGS){int x=SIDE_W+24,y=TOP_H+20,cw=((int)fb_width()-x-32)/2;for(int i=0;i<6;i++){int bx=x+(i%2)*(cw+12),by=y+66+(i/2)*92;if(inside(mx,my,bx,by,cw,78)){if(i<5)toggle_setting(i);else nova_settings_save();return;}}}}

void gui_init(void){mouse_set_bounds((int)fb_width(),(int)fb_height());terminal_cwd=fat32_is_mounted()?fat32_root_cluster():0;strcpy(terminal_output,"ZapOS Nova Maximal Edition\nKernel services online. Type help for commands.\n");terminal_output_len=(int)strlen(terminal_output);if(fat32_is_mounted())file_count=fat32_list_dir(fat32_root_cluster(),files,18);nova_browser_init(&browser_state);nova_editor_init(&editor_state,terminal_cwd);nova_editor_new(&editor_state,"UNTITLED.TXT");nova_wm_init((int)fb_width(),(int)fb_height(),TOP_H,DOCK_H);nova_notice_post(NOVA_SUCCESS,"Nova Maximal online","Browser, editor and window manager are ready.");}
void gui_run(void){uint32_t pulse=0;for(;;){if(fullscreen_active){if(scheduler_task_state(fullscreen_owner)==TASK_TERMINATED){fullscreen_active=0;fullscreen_owner=-1;}else{fb_fill_rect(0,0,(int)fb_width(),(int)fb_height(),0);fb_blit_rgb(0,0,(int)fb_width(),(int)fb_height(),fullscreen_buffer,DOOM_BLIT_W,DOOM_BLIT_H);fb_swap_buffers();pit_sleep(10);continue;}}if(pit_ticks()-pulse>=25){nova_pulse();pulse=pit_ticks();}int mx,my;uint8_t b;mouse_get_state(&mx,&my,&b);int left=(b&MOUSE_LEFT_BUTTON)!=0;if(left&&!previous_left)click(mx,my);else if(left&&previous_left&&window_mode)nova_wm_move_pointer(mx,my);else if(!left&&previous_left&&window_mode)nova_wm_end_pointer();previous_left=left;char c;while((c=keyboard_getchar())!=0)key(c);wallpaper();topbar();sidebar();if(active_app==NOVA_APP_HOME)home();else if(active_app==NOVA_APP_TERMINAL)terminal();else if(active_app==NOVA_APP_FILES)files_view();else if(active_app==NOVA_APP_TASKS)tasks_view();else if(active_app==NOVA_APP_BROWSER)browser_view();else if(active_app==NOVA_APP_EDITOR)editor_view();else if(active_app==NOVA_APP_ACTIVITY)activity_view();else if(active_app==NOVA_APP_SETTINGS)settings_view();else system_view();dock();windows_overlay();overlay_panels();cursor(mx,my);fb_swap_buffers();struct nova_settings s;nova_settings_get(&s);pit_sleep(s.performance_mode?22:10);}}
